// No model list, SAT calls, or graph catalogue. Derive link constraints from address masks.
use std::collections::HashSet;
type B=u128;
struct Rules{pos:Vec<B>,neg:Vec<B>,stars:Vec<(B,u32,u32)>}
fn unit(r:&Rules,mut on:B,mut off:B,degree:bool)->Option<(B,B)>{loop{let was=(on,off);for &p in &r.pos{if p&on!=0{continue}let u=p&!off;if u==0{return None}if u.is_power_of_two(){on|=u}}
for &t in &r.neg{if t&off!=0{continue}let u=t&!on;if u==0{return None}if u.is_power_of_two(){off|=u}}
if degree{for &(s,lo,hi) in &r.stars{let a=(s&on).count_ones();let b=(s&!off).count_ones();if a>hi||b<lo{return None}if a==hi{off|=s&!on}if b==lo{on|=s&!off}}}
if on&off!=0{return None}if was==(on,off){return Some(was)}}}
fn close(r:&Rules,on:B,off:B,level:u32)->Option<(B,B)>{let(mut a,mut b)=unit(r,on,off,true)?;if level==0{return Some((a,b))}loop{let was=(a,b);let mut u=((1<<80)-1)&!(a|b);while u!=0{let t=u&u.wrapping_neg();u^=t;if close(r,a|t,b,level-1).is_none(){(a,b)=unit(r,a,b|t,true)?}else if close(r,a,b|t,level-1).is_none(){(a,b)=unit(r,a|t,b,true)?}u&=!(a|b)}if was==(a,b){return Some(was)}}}
fn main(){let mut s=vec![];for i in 0..7{for j in i+1..7{if [(0,1),(2,3),(4,5)].contains(&(i,j)){continue}s.push((1u32<<i)|(1<<j))}}s.push(60);let mut edges=vec![];let mut em=[[0u128;19];19];for i in 0..19{for j in i+1..19{if s[i]&s[j]==0{let t=1u128<<edges.len();em[i][j]=t;em[j][i]=t;edges.push((i,j))}}}assert_eq!(edges.len(),80);let mut neg=vec![];for i in 0..19{for j in i+1..19{for k in j+1..19{let t=em[i][j]|em[i][k]|em[j][k];if t.count_ones()==3{neg.push(t)}}}}
let mut pos=HashSet::new();let mut ban=vec![false;1<<19];for mask in 1usize..1<<19{let n=mask.count_ones();if n>7{continue}let ids:Vec<_>=(0..19).filter(|i|mask>>i&1!=0).collect();if ids.iter().any(|i|ban[mask^(1<<i)]){ban[mask]=true;continue}let labels=ids.iter().fold(0,|x,&i|x|s[i]);if n==7||labels.count_ones()<n{ban[mask]=true;let mut c=0;for &i in &ids{for &j in &ids{c|=em[i][j]}}pos.insert(c);}}
let mut pos:Vec<_>=pos.into_iter().collect();pos.sort_by_key(|x|(x.count_ones(),*x));let stars=(0..19).map(|i|(em[i].iter().fold(0,|a,b|a|b),4-s[i].count_ones(),7-s[i].count_ones())).collect();let r=Rules{pos,neg,stars};println!("clauses {} positive {} negative",r.pos.len(),r.neg.len());let level=std::env::args().nth(1).unwrap_or("1".into()).parse().unwrap();for code in 0..8{let mut a=0;let mut b=0;for (i,j) in [0,4,6].iter().enumerate(){if code>>i&1!=0{a|=1<<j}else{b|=1<<j}}let mut counts=vec![];let (u,v)=unit(&r,a,b,false).unwrap();counts.push((u|v).count_ones());for l in 0..=level{let (u,v)=close(&r,a,b,l).unwrap();counts.push((u|v).count_ones());if l==level && (u|v).count_ones()==80{print!("mask={} ",u)}}println!("{} {:?}",code,counts)}}
